import{_ as p,a0 as r,w as l,s as o,ao as c,I as n,x as s,a1 as i,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"17 个 tar 命令实用示例 | LCTT x X-CMD","titleTemplate":false,"description":"17 个 tar 命令实用示例 | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"17 个 tar 命令实用示例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"17 个 tar 命令实用示例 | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160911 17 tar command practical examples in Linux","title":"17 个 tar 命令实用示例","tag":"201609","desc":""},"relativePath":"201609/20160911 17 tar command practical examples in Linux.md","filePath":"[post].md"}'),h={name:"201609/20160911 17 tar command practical examples in Linux.md"};function d(g,a,k,b,u,x){const t=r("Link");return l(),o("div",null,[a[13]||(a[13]=c(`<h1 id="_17-个-tar-命令实用示例" tabindex="-1">17 个 tar 命令实用示例 <a class="header-anchor" href="#_17-个-tar-命令实用示例" aria-label="Permalink to “17 个 tar 命令实用示例”">​</a></h1><p>Tar（Tape ARchive，磁带归档的缩写，LCTT 译注：最初设计用于将文件打包到磁带上，现在我们大都使用它来实现备份某个分区或者某些重要的目录）是类 Unix 系统中使用最广泛的命令，用于归档多个文件或目录到单个归档文件中，并且归档文件可以进一步使用 gzip 或者 bzip2 等技术进行压缩。换言之，tar 命令也可以用于备份：先是归档多个文件和目录到一个单独的 tar 文件或归档文件，然后在需要之时将 tar 文件中的文件和目录释放出来。</p><p>本文将介绍 tar 的 17 个实用示例。</p><p>tar 命令语法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tar &lt;选项&gt; &lt;文件&gt;</span></span></code></pre></div><p>下面列举 tar 命令中一些常用的选项：</p><blockquote><p>--delete : 从归档文件 (而非磁带) 中删除</p></blockquote><blockquote><p>-r, --append : 将文件追加到归档文件中</p></blockquote><blockquote><p>-t, --list : 列出归档文件中包含的内容</p></blockquote><blockquote><p>--test-label : 测试归档文件卷标并退出</p></blockquote><blockquote><p>-u, --update : 将已更新的文件追加到归档文件中</p></blockquote><blockquote><p>-x, --extract, --get : 释放归档文件中文件及目录</p></blockquote><blockquote><p>-C, --directory=DIR : 执行归档动作前变更工作目录到 DIR</p></blockquote><blockquote><p>-f, --file=ARCHIVE : 指定 (将要创建或已存在的) 归档文件名</p></blockquote><blockquote><p>-j, --bip2 : 对归档文件使用 bzip2 压缩</p></blockquote><blockquote><p>-J, --xz : 对归档文件使用 xz 压缩</p></blockquote><blockquote><p>-p, --preserve-permissions : 保留原文件的访问权限</p></blockquote><blockquote><p>-v, --verbose : 显示命令整个执行过程</p></blockquote><blockquote><p>-z, gzip : 对归档文件使用 gzip 压缩</p></blockquote><p>注 : 在 tar 命令选项中的连接符 <code>-</code> 是可选的（LCTT 译注：不用 <code>-</code> 也没事。这在 GNU 软件里面很罕见，大概是由于 tar 命令更多受到古老的 UNIX 风格影响）。</p><h3 id="示例-1-创建一个-tar-归档文件" tabindex="-1">示例 1：创建一个 tar 归档文件 <a class="header-anchor" href="#示例-1-创建一个-tar-归档文件" aria-label="Permalink to “示例 1：创建一个 tar 归档文件”">​</a></h3><p>现在来创建一个 tar 文件，将 /etc/ 目录和 /root/anaconda-ks.cfg 文件打包进去。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -cvf myarchive.tar /etc /root/anaconda-ks.cfg</span></span></code></pre></div><p>以上命令会在当前目录创建一个名为 &quot;myarchive&quot; 的 tar 文件，内含 /etc/ 目录和 /root/anaconda-ks.cfg 文件。</p><p>其中，<code>-c</code> 选项表示要创建 tar 文件，<code>-v</code> 选项用于输出 tar 的详细过程到屏幕上，<code>-f</code> 选项则是指定归档文件名称。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# ls -l myarchive.tar</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 22947840 Sep 7 00:24 myarchive.tar</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><h3 id="示例-2-列出归档文件中的内容" tabindex="-1">示例 2：列出归档文件中的内容 <a class="header-anchor" href="#示例-2-列出归档文件中的内容" aria-label="Permalink to “示例 2：列出归档文件中的内容”">​</a></h3><p>在 tar 命令中使用 <code>–t</code> 选项可以不用释放其中的文件就可以快速列出文件中包含的内容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -tvf myarchive.tar</span></span></code></pre></div><p>列出 tar 文件中的指定的文件和目录。下列命令尝试查看 anaconda-ks.cfg 文件是否存在于 tar 文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -tvf myarchive.tar root/anaconda-ks.cfg</span></span>
<span class="line"><span>-rw------- root/root 953 2016-08-24 01:33 root/anaconda-ks.cfg</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><h3 id="示例-3-追加文件到归档-tar-文件中" tabindex="-1">示例 3：追加文件到归档（tar）文件中 <a class="header-anchor" href="#示例-3-追加文件到归档-tar-文件中" aria-label="Permalink to “示例 3：追加文件到归档（tar）文件中”">​</a></h3><p><code>-r</code> 选项用于向已有的 tar 文件中追加文件。下面来将 /etc/fstab 添加到 data.tar 中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -rvf data.tar /etc/fstab</span></span></code></pre></div><p>注：在压缩过的 tar 文件中无法进行追加文件操作。</p><h3 id="示例-4-从-tar-文件中释放文件以及目录" tabindex="-1">示例 4：从 tar 文件中释放文件以及目录 <a class="header-anchor" href="#示例-4-从-tar-文件中释放文件以及目录" aria-label="Permalink to “示例 4：从 tar 文件中释放文件以及目录”">​</a></h3><p><code>-x</code> 选项用于释放出 tar 文件中的文件和目录。下面来释放上边创建的 tar 文件中的内容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -xvf myarchive.tar</span></span></code></pre></div><p>这个命令会在当前目录中释放出 myarchive.tar 文件中的内容。</p><h3 id="示例-5-释放-tar-文件到指定目录" tabindex="-1">示例 5：释放 tar 文件到指定目录 <a class="header-anchor" href="#示例-5-释放-tar-文件到指定目录" aria-label="Permalink to “示例 5：释放 tar 文件到指定目录”">​</a></h3><p>假如你想要释放 tar 文件中的内容到指定的文件夹或者目录，使用 <code>-C</code> 选项后边加上指定的文件的路径。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -xvf myarchive.tar -C /tmp/</span></span></code></pre></div><h3 id="示例-6-释放-tar-文件中的指定文件或目录" tabindex="-1">示例 6：释放 tar 文件中的指定文件或目录 <a class="header-anchor" href="#示例-6-释放-tar-文件中的指定文件或目录" aria-label="Permalink to “示例 6：释放 tar 文件中的指定文件或目录”">​</a></h3><p>假设你只要释放 tar 文件中的 anaconda-ks.cfg 到 /tmp 目录。</p><p>语法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tar –xvf {tar-file } {file-to-be-extracted } -C {path-where-to-extract}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[root@linuxtechi tmp]# tar -xvf /root/myarchive.tar root/anaconda-ks.cfg -C /tmp/</span></span>
<span class="line"><span>root/anaconda-ks.cfg</span></span>
<span class="line"><span>[root@linuxtechi tmp]# ls -l /tmp/root/anaconda-ks.cfg</span></span>
<span class="line"><span>-rw-------. 1 root root 953 Aug 24 01:33 /tmp/root/anaconda-ks.cfg</span></span>
<span class="line"><span>[root@linuxtechi tmp]#</span></span></code></pre></div><h3 id="示例-7-创建并压缩归档文件-tar-gz-或-tgz" tabindex="-1">示例 7：创建并压缩归档文件（.tar.gz 或 .tgz） <a class="header-anchor" href="#示例-7-创建并压缩归档文件-tar-gz-或-tgz" aria-label="Permalink to “示例 7：创建并压缩归档文件（.tar.gz 或 .tgz）”">​</a></h3><p>假设我们需要打包 /etc 和 /opt 文件夹，并用 gzip 工具将其压缩。可以在 tar 命令中使用 <code>-z</code> 选项来实现。这种 tar 文件的扩展名可以是 .tar.gz 或者 .tgz。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -zcpvf myarchive.tar.gz /etc/ /opt/</span></span></code></pre></div><p>或</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -zcpvf myarchive.tgz /etc/ /opt/</span></span></code></pre></div><h3 id="示例-8-创建并压缩归档文件-tar-bz2-或-tbz2" tabindex="-1">示例 8：创建并压缩归档文件（.tar.bz2 或 .tbz2） <a class="header-anchor" href="#示例-8-创建并压缩归档文件-tar-bz2-或-tbz2" aria-label="Permalink to “示例 8：创建并压缩归档文件（.tar.bz2 或 .tbz2）”">​</a></h3><p>假设我们需要打包 /etc 和 /opt 文件夹，并使用 bzip2 压缩。可以在 tar 命令中使用 <code>-j</code> 选项来实现。这种 tar 文件的扩展名可以是 .tar.bz2 或者 .tbz。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -jcpvf myarchive.tar.bz2 /etc/ /opt/</span></span></code></pre></div><p>或</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -jcpvf myarchive.tbz2 /etc/ /opt/</span></span></code></pre></div><h3 id="示例-9-排除指定文件或类型后创建-tar-文件" tabindex="-1">示例 9：排除指定文件或类型后创建 tar 文件 <a class="header-anchor" href="#示例-9-排除指定文件或类型后创建-tar-文件" aria-label="Permalink to “示例 9：排除指定文件或类型后创建 tar 文件”">​</a></h3><p>创建 tar 文件时在 tar 命令中使用 <code>–exclude</code> 选项来排除指定文件或者类型。假设在创建压缩的 tar 文件时要排除 .html 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -zcpvf myarchive.tgz /etc/ /opt/ --exclude=*.html</span></span></code></pre></div><h3 id="示例-10-列出-tar-gz-或-tgz-文件中的内容" tabindex="-1">示例 10：列出 .tar.gz 或 .tgz 文件中的内容 <a class="header-anchor" href="#示例-10-列出-tar-gz-或-tgz-文件中的内容" aria-label="Permalink to “示例 10：列出 .tar.gz 或 .tgz 文件中的内容”">​</a></h3><p>使用 <code>-t</code> 选项可以查看 .tar.gz 或 .tgz 文件中内容。如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -tvf myarchive.tgz  | more</span></span>
<span class="line"><span>.............................................</span></span>
<span class="line"><span>drwxr-xr-x root/root         0 2016-09-07 08:41 etc/</span></span>
<span class="line"><span>-rw-r--r-- root/root       541 2016-08-24 01:23 etc/fstab</span></span>
<span class="line"><span>-rw------- root/root         0 2016-08-24 01:23 etc/crypttab</span></span>
<span class="line"><span>lrwxrwxrwx root/root         0 2016-08-24 01:23 etc/mtab -&gt; /proc/self/mounts</span></span>
<span class="line"><span>-rw-r--r-- root/root       149 2016-09-07 08:41 etc/resolv.conf</span></span>
<span class="line"><span>drwxr-xr-x root/root         0 2016-09-06 03:55 etc/pki/</span></span>
<span class="line"><span>drwxr-xr-x root/root         0 2016-09-06 03:15 etc/pki/rpm-gpg/</span></span>
<span class="line"><span>-rw-r--r-- root/root      1690 2015-12-09 04:59 etc/pki/rpm-gpg/RPM-GPG-KEY-CentOS-7</span></span>
<span class="line"><span>-rw-r--r-- root/root      1004 2015-12-09 04:59 etc/pki/rpm-gpg/RPM-GPG-KEY-CentOS-Debug-7</span></span>
<span class="line"><span>-rw-r--r-- root/root      1690 2015-12-09 04:59 etc/pki/rpm-gpg/RPM-GPG-KEY-CentOS-Testing-7</span></span>
<span class="line"><span>-rw-r--r-- root/root      3140 2015-09-15 06:53 etc/pki/rpm-gpg/RPM-GPG-KEY-foreman</span></span>
<span class="line"><span>..........................................................</span></span></code></pre></div><h3 id="示例-11-列出-tar-bz2-或-tbz2-文件中的内容" tabindex="-1">示例 11：列出 .tar.bz2 或 .tbz2 文件中的内容 <a class="header-anchor" href="#示例-11-列出-tar-bz2-或-tbz2-文件中的内容" aria-label="Permalink to “示例 11：列出 .tar.bz2 或 .tbz2 文件中的内容”">​</a></h3><p>使用 <code>-t</code> 选项可以查看 .tar.bz2 或 .tbz2 文件中内容。如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -tvf myarchive.tbz2  | more</span></span>
<span class="line"><span>........................................................</span></span>
<span class="line"><span>rwxr-xr-x root/root         0 2016-08-24 01:25 etc/pki/java/</span></span>
<span class="line"><span>lrwxrwxrwx root/root         0 2016-08-24 01:25 etc/pki/java/cacerts -&gt; /etc/pki/ca-trust/extracted/java/cacerts</span></span>
<span class="line"><span>drwxr-xr-x root/root         0 2016-09-06 02:54 etc/pki/nssdb/</span></span>
<span class="line"><span>-rw-r--r-- root/root     65536 2010-01-12 15:09 etc/pki/nssdb/cert8.db</span></span>
<span class="line"><span>-rw-r--r-- root/root      9216 2016-09-06 02:54 etc/pki/nssdb/cert9.db</span></span>
<span class="line"><span>-rw-r--r-- root/root     16384 2010-01-12 16:21 etc/pki/nssdb/key3.db</span></span>
<span class="line"><span>-rw-r--r-- root/root     11264 2016-09-06 02:54 etc/pki/nssdb/key4.db</span></span>
<span class="line"><span>-rw-r--r-- root/root       451 2015-10-21 09:42 etc/pki/nssdb/pkcs11.txt</span></span>
<span class="line"><span>-rw-r--r-- root/root     16384 2010-01-12 15:45 etc/pki/nssdb/secmod.db</span></span>
<span class="line"><span>drwxr-xr-x root/root         0 2016-08-24 01:26 etc/pki/CA/</span></span>
<span class="line"><span>drwxr-xr-x root/root         0 2015-06-29 08:48 etc/pki/CA/certs/</span></span>
<span class="line"><span>drwxr-xr-x root/root         0 2015-06-29 08:48 etc/pki/CA/crl/</span></span>
<span class="line"><span>drwxr-xr-x root/root         0 2015-06-29 08:48 etc/pki/CA/newcerts/</span></span>
<span class="line"><span>drwx------ root/root         0 2015-06-29 08:48 etc/pki/CA/private/</span></span>
<span class="line"><span>drwx------ root/root         0 2015-11-20 06:34 etc/pki/rsyslog/</span></span>
<span class="line"><span>drwxr-xr-x root/root         0 2016-09-06 03:44 etc/pki/pulp/</span></span>
<span class="line"><span>..............................................................</span></span></code></pre></div><h3 id="示例-12-解压-tar-gz-或-tgz-文件" tabindex="-1">示例 12：解压 .tar.gz 或 .tgz 文件 <a class="header-anchor" href="#示例-12-解压-tar-gz-或-tgz-文件" aria-label="Permalink to “示例 12：解压 .tar.gz 或 .tgz 文件”">​</a></h3><p>使用 <code>-x</code> 和 <code>-z</code> 选项来解压 .tar.gz 或 .tgz 文件。如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -zxpvf myarchive.tgz -C /tmp/</span></span></code></pre></div><p>以上命令将 tar 文件解压到 /tmp 目录。</p><p>注：现今的 tar 命令会在执行解压动作前自动检查文件的压缩类型，这意味着我们在使用 tar 命令是可以不用指定文件的压缩类型。如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -xpvf myarchive.tgz -C /tmp/</span></span></code></pre></div><h3 id="示例-13-解压-tar-bz2-或-tbz2-文件" tabindex="-1">示例 13：解压 .tar.bz2 或 .tbz2 文件 <a class="header-anchor" href="#示例-13-解压-tar-bz2-或-tbz2-文件" aria-label="Permalink to “示例 13：解压 .tar.bz2 或 .tbz2 文件”">​</a></h3><p>使用 <code>-j</code> 和 <code>-x</code> 选项来解压 .tar.bz2 或 .tbz2 文件。如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -jxpvf myarchive.tbz2 -C /tmp/</span></span></code></pre></div><p>或</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar xpvf myarchive.tbz2 -C /tmp/</span></span></code></pre></div><h3 id="示例-14-使用-tar-命令进行定时备份" tabindex="-1">示例 14：使用 tar 命令进行定时备份 <a class="header-anchor" href="#示例-14-使用-tar-命令进行定时备份" aria-label="Permalink to “示例 14：使用 tar 命令进行定时备份”">​</a></h3><p>总有一些实时场景需要我们对指定的文件和目录进行打包，已达到日常备份的目的。假设需要每天备份整个 /opt 目录，可以创建一个带 tar 命令的 cron 任务来完成。如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -zcvf optbackup-$(date +%Y-%m-%d).tgz /opt/</span></span></code></pre></div><p>为以上命令创建一个 cron 任务即可。</p><h3 id="示例-15-使用-t-及-x-创建压缩归档文件" tabindex="-1">示例 15：使用 -T 及 -X 创建压缩归档文件 <a class="header-anchor" href="#示例-15-使用-t-及-x-创建压缩归档文件" aria-label="Permalink to “示例 15：使用 -T 及 -X 创建压缩归档文件”">​</a></h3><p>想像这样一个场景：把想要归档和压缩的文件及目录记录到到一个文件，然后把这个文件当做 tar 命令的传入参数来完成归档任务；而有时候则是需要排除上面提到的这个文件里面记录的特定路径后进行归档和压缩。</p><p>在 tar 命令中使用 <code>-T</code> 选项来指定该输入文件，使用 <code>-X</code> 选项来指定包含要排除的文件列表。</p><p>假设要归档 /etc、/opt、/home 目录，并排除 /etc/sysconfig/kdump 和 /etc/sysconfig/foreman 文件，可以创建 /root/tar-include 和 /root/tar-exclude 然后分别输入以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# cat /root/tar-include</span></span>
<span class="line"><span>/etc</span></span>
<span class="line"><span>/opt</span></span>
<span class="line"><span>/home</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span>
<span class="line"><span>[root@linuxtechi ~]# cat /root/tar-exclude</span></span>
<span class="line"><span>/etc/sysconfig/kdump</span></span>
<span class="line"><span>/etc/sysconfig/foreman</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>运行以下命令来创建一个压缩归档文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar zcpvf mybackup-$(date +%Y-%m-%d).tgz -T /root/tar-include -X /root/tar-exclude</span></span></code></pre></div><h3 id="示例-16-查看-tar、-tgz-和-tbz2-文件的大小" tabindex="-1">示例 16：查看 .tar、.tgz 和 .tbz2 文件的大小 <a class="header-anchor" href="#示例-16-查看-tar、-tgz-和-tbz2-文件的大小" aria-label="Permalink to “示例 16：查看 .tar、.tgz 和 .tbz2 文件的大小”">​</a></h3><p>使用如下命令来查看 (压缩) tar 文件的体积。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# tar -czf - data.tar | wc -c</span></span>
<span class="line"><span>427</span></span>
<span class="line"><span>[root@linuxtechi ~]# tar -czf - mybackup-2016-09-09.tgz | wc -c</span></span>
<span class="line"><span>37956009</span></span>
<span class="line"><span>[root@linuxtechi ~]# tar -czf - myarchive.tbz2 | wc -c</span></span>
<span class="line"><span>30835317</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><h3 id="示例-17-分割体积庞大的-tar-文件为多份小文件" tabindex="-1">示例 17：分割体积庞大的 tar 文件为多份小文件 <a class="header-anchor" href="#示例-17-分割体积庞大的-tar-文件为多份小文件" aria-label="Permalink to “示例 17：分割体积庞大的 tar 文件为多份小文件”">​</a></h3><p>类 Unix 系统中使用 split 命令来将大体积文件分割成小体积文件。大体积的 tar 当然也可以使用这个命令来进行分割。</p><p>假设需要将 &quot;mybackup-2016-09-09.tgz&quot; 分割成每份 6 MB 的小文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Syntax :  split -b &lt;Size-in-MB&gt; &lt;tar-file-name&gt;.&lt;extension&gt; “prefix-name”</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# split -b 6M mybackup-2016-09-09.tgz mybackup-parts</span></span></code></pre></div><p>以上命令会在当前目录分割 mybackup-2016-09-09.tgz 文件成为多个 6 MB 的小文件，文件名为 mybackup-partsaa ~ mybackup-partsag。如果在要在分割文件后以数字而非字母来区分，可以在以上的 split 命令使用 <code>-d</code> 选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# ls -l mybackup-parts*</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 6291456 Sep 10 03:05 mybackup-partsaa</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 6291456 Sep 10 03:05 mybackup-partsab</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 6291456 Sep 10 03:05 mybackup-partsac</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 6291456 Sep 10 03:05 mybackup-partsad</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 6291456 Sep 10 03:05 mybackup-partsae</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 6291456 Sep 10 03:05 mybackup-partsaf</span></span>
<span class="line"><span>-rw-r--r--. 1 root root 637219  Sep 10 03:05 mybackup-partsag</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>然后通过网络将这些分割文件转移到其他服务器，就可以合并成为一个单独的 tar 文件了，如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@linuxtechi ~]# cat mybackup-partsa* &gt; mybackup-2016-09-09.tgz</span></span>
<span class="line"><span>[root@linuxtechi ~]#</span></span></code></pre></div><p>文毕，希望你喜欢 tar 命令的这几个不同的示例。随时评论并分享你的心得。</p><hr>`,101)),n("p",null,[a[1]||(a[1]=s("via: ",-1)),i(t,{href:"http://www.linuxtechi.com/17-tar-command-examples-in-linux/"},{default:e(()=>[...a[0]||(a[0]=[s("http://www.linuxtechi.com/17-tar-command-examples-in-linux/",-1)])]),_:1})]),n("p",null,[a[5]||(a[5]=s("作者：",-1)),i(t,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:e(()=>[...a[2]||(a[2]=[s("Pradeep Kumar",-1)])]),_:1}),a[6]||(a[6]=s(" 译者：",-1)),i(t,{href:"https://github.com/GHLandy"},{default:e(()=>[...a[3]||(a[3]=[s("GHLandy",-1)])]),_:1}),a[7]||(a[7]=s(" 校对：",-1)),i(t,{href:"https://github.com/wxy"},{default:e(()=>[...a[4]||(a[4]=[s("wxy",-1)])]),_:1})]),n("p",null,[a[10]||(a[10]=s("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...a[8]||(a[8]=[s("LCTT",-1)])]),_:1}),a[11]||(a[11]=s(" 原创编译，",-1)),i(t,{href:"https://linux.cn/"},{default:e(()=>[...a[9]||(a[9]=[s("Linux中国",-1)])]),_:1}),a[12]||(a[12]=s(" 荣誉推出",-1))])])}const v=p(h,[["render",d]]);export{y as __pageData,v as default};
